plugins {
    java
}

java {
    toolchain {
        languageVersion = JavaLanguageVersion.of(17)
    }
}

repositories {
    mavenCentral()
}

// Generated by buf from ../protos (see protos/buf.gen.yaml) and committed.
sourceSets {
    main {
        java {
            srcDir("src/main/gen")
        }
    }
}

// grpc and protobuf match the buf plugin versions in protos/buf.gen.yaml.
dependencies {
    implementation("com.google.protobuf:protobuf-java:4.36.2")
    implementation("io.grpc:grpc-protobuf:1.84.0")
    implementation("io.grpc:grpc-stub:1.84.0")

    testImplementation(platform("org.junit:junit-bom:5.13.4"))
    testImplementation("org.junit.jupiter:junit-jupiter")
    testRuntimeOnly("org.junit.platform:junit-platform-launcher")
}

tasks.test {
    useJUnitPlatform()
}
